            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return WhatsAppTemplate::fromArray($response->data());
    }

    /**
     * Preview Template.
     *
     * Preview a template with variable substitution
     *
     * Returns the template with placeholders replaced using either: - Contact data (if contact_id
     * provided) - Override values (if variable_values provided) - Sample data (if neither provided)
     *
     * Useful for testing variable mappings before sending.
     *
     * Scopes: channels:read.
     *
     * @param  ?string  $contactId  Contact ID to use for preview (optional - uses sample data if not provided)
     * @param  array<string, mixed>|null  $variableValues  Override values for preview
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/WhatsApp%20Templates/preview_template_api_v1_whatsapp_templates__template_id__preview_post
     */
    public function preview(string $templateId, ?string $contactId = null, ?array $variableValues = null, ?string $idempotencyKey = null): PreviewTemplate
    {
        $response = $this->connector->send(new Request(
            Method::Post,
            '/whatsapp-templates/'.Payload::segment($templateId).'/preview',
            body: Payload::body(['contact_id' => $contactId, 'variable_values' => $variableValues]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));

        return PreviewTemplate::fromArray($response->data());
    }

    /**
     * Update Variable Mapping.
     *
     * Update variable mapping for a template
     *
     * Maps WhatsApp template placeholders ({{1}}, {{2}}, etc.) to contact fields for automatic
     * personalization when sending messages.
     *
     * Example mapping:
     *
     * Scopes: channels:update.
     *
     * @param  array<string, mixed>  $variableMapping  Map placeholders to contact fields: {'1': 'contact.first_name'}
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/WhatsApp%20Templates/update_variable_mapping_api_v1_whatsapp_templates__template_id__variable_mapping_put
     */
    public function updateVariableMapping(string $templateId, array $variableMapping): UpdateVariableMapping
    {
        $response = $this->connector->send(new Request(
            Method::Put,
            '/whatsapp-templates/'.Payload::segment($templateId).'/variable-mapping',
            body: Payload::body(['variable_mapping' => $variableMapping]),
        ));

        return UpdateVariableMapping::fromArray($response->data());
    }
}
